import React from 'react';
import {Divider, message as messageApi} from 'antd';
import {ProForm, ProFormRadio} from '@ant-design/pro-form';
import {LocaleTextarea} from '@yookue/ant-buddy-pro';
import {type TabsPosition} from '@yookue/ant-buddy-pro/layout/CardTabs';


export default () => {
    const [messageInvoker, messageContext] = messageApi.useMessage();
    const [tabPos, setTabPos] = React.useState<TabsPosition>('top');

    return (
        <>
            {messageContext}
            <ProForm
                name='LocaleTextarea_demo1.zh-TW'
                layout='vertical'
                autoFocusFirstInput={false}
                submitter={{
                    searchConfig: {
                        submitText: '提交',
                        resetText: '重置',
                    }
                }}
                onFinish={async () => {
                    messageInvoker.success('您點擊了提交按鈕');
                }}
            >
                <ProFormRadio.Group
                    label='Tab 位置'
                    radioType='button'
                    fieldProps={{
                        value: tabPos,
                        buttonStyle: 'solid',
                        onChange: (event) => {
                            setTabPos(event.target?.value);
                        }
                    }}
                    options={[
                        {label: '上', value: 'top'},
                        {label: '下', value: 'bottom'},
                        {label: '左', value: 'left'},
                        {label: '右', value: 'right'},
                        {label: '上-末尾', value: 'top-end'},
                        {label: '下-末尾', value: 'bottom-end'},
                    ]}
                />
                <Divider/>
                <LocaleTextarea
                    name='foobar'
                    placeholder='示例字段-帶校驗'
                    fieldProps={{
                        autoSize: {
                            minRows: 6,
                            maxRows: 8,
                        }
                    }}
                    rules={[
                        {
                            required: true,
                            message: '請輸入示例字段',
                        },
                    ]}
                    tabsProps={{
                        tabPosition: tabPos,
                    }}
                    locale='zh_TW'
                    switchTextareaProps={[
                        {
                            tag: 'en-US',
                            placeholder: '示例字段-英文',
                            allowClear: true,
                        },
                        {
                            tag: 'zh-CN',
                            placeholder: '示例字段-簡體中文',
                            allowClear: true,
                        },
                        {
                            tag: 'zh-TW',
                            placeholder: '示例字段-繁體中文',
                            allowClear: true,
                        }
                    ]}
                    switchShareProps={{
                        rules: [
                            {
                                type: 'string',
                                min: 2,
                                max: 60,
                                message: '示例字段的長度必須在 2~60 之間',
                            }
                        ]
                    }}
                />
            </ProForm>
        </>
    );
}
